def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if not isinstance(path, str) or not isinstance(cwd, str):
        return None

    if not path.startswith('/'):
        path = cwd + '/' + path

    comps = split(path)
    result = []
    link_count = 0

    while comps:
        c = comps.pop(0)
        if c == '..':
            if result:
                result.pop()
            continue
        else:
            result.append(c)
            current = '/' + '/'.join(result)
            if current in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[current]
                # remove the link component itself; it will be replaced
                result.pop()
                if not isinstance(target, str):
                    return None
                if not target.startswith('/'):
                    dir_path = '/' + '/'.join(result)
                    target = dir_path + '/' + target
                target_comps = split(target)
                comps = target_comps + comps

    if not result:
        return '/'
    return '/' + '/'.join(result)

